def parse_home_address(addr_str):
    lines = [ln.strip() for ln in addr_str.split('\n') if ln.strip()!='']
    if len(lines)!=5:
        raise ValueError(f'Unexpected address lines ({len(lines)}): {addr_str!r}')
    street, city, state, country, zip_code = lines
    return {'street_address': street, 'city': city, 'state': state, 'country': country, 'zip_code': int(zip_code)}

def norm(s):
    return ' '.join(str(s).lower().split())

# existing match keys
existing_matches = {}
for a in addresses:
    existing_matches[(int(a['zip_code']), norm(a['street_address']), norm(a['city']), norm(a['state']), norm(a['country']))] = a['address_id']

missing_groups=[]
