    p=parse_home_address(addr_str)
    key=(p['zip_code'], norm(p['street_address']), norm(p['city']), norm(p['state']), norm(p['country']))
    matched_id=existing_matches.get(key)
    if matched_id is None:
        missing_groups.append((addr_str, plist, p))

